<?php
namespace App\Http\Controllers\Api\V1\Guest;
use App\Http\Controllers\Controller; use App\Models\{MenuItem,Outlet,PosOrder,Stay}; use App\Services\POS\PosService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class GuestDiningController extends Controller{private function guest(Request $r){abort_unless($r->user()->role==='guest'&&$r->user()->guest_id,403);return $r->user()->guest;}
 public function menu(Request $r){$g=$this->guest($r);return ['outlets'=>Outlet::where('property_id',$g->property_id)->where('is_active',1)->get(),'items'=>MenuItem::with('category')->where('property_id',$g->property_id)->where('is_active',1)->paginate(100)];}
 public function orders(Request $r){$g=$this->guest($r);return PosOrder::with(['outlet','items','payments'])->where('guest_id',$g->id)->latest()->paginate(30);}
 public function store(Request $r,PosService $pos){$g=$this->guest($r);$d=$r->validate(['outlet_id'=>'required|integer','service_type'=>'required|in:takeaway,delivery,room_service','stay_id'=>'nullable|integer','notes'=>'nullable|string|max:1000','items'=>'required|array|min:1','items.*.menu_item_id'=>'required|integer','items.*.quantity'=>'required|numeric|min:0.001','items.*.notes'=>'nullable|string|max:500']);if($d['service_type']==='room_service'){abort_unless(!empty($d['stay_id'])&&Stay::where('id',$d['stay_id'])->where('guest_id',$g->id)->where('status','in_house')->exists(),422,'An active in-house stay is required for room service.');}$order=DB::transaction(function()use($d,$g,$r,$pos){Outlet::where('property_id',$g->property_id)->where('is_active',1)->findOrFail($d['outlet_id']);$o=$pos->createOrder($d,$g->property_id,$r->user()->id);foreach($d['items'] as $line){$m=MenuItem::where('property_id',$g->property_id)->findOrFail($line['menu_item_id']);$pos->addItem($o,$m,(float)$line['quantity'],[],$line['notes']??null);}return $pos->sendToKitchen($o)->order()->first();});return response()->json($order->load('items'),201);}}
